#!/usr/bin/env python3
"""Recheck the word-edge method on 7/5, K=2048, added primes 3,11,13.

Requires Python 3.10+ and g++ with C++17 support. Both C++ sources are embedded.
All intermediate full graphs are compared byte-for-byte. Does not reverify the
original 5/2 result or claim new Lean formalization.
"""
from pathlib import Path
import argparse, subprocess, json, hashlib
SOURCE_A = '// Exact certificate construction A for floor(xi*(7/5)^n).\n// Integer interval enumeration, root-mask prime lifts, Kosaraju components.\n// All resource cutoffs are failures/inconclusive, never a successful certificate.\n// Build: g++ -std=c++17 -O2 construction_a.cpp -o construction_a\n// Run: ./construction_a OUTPUT_DIRECTORY\n#include <algorithm>\n#include <chrono>\n#include <cstdint>\n#include <iostream>\n#include <numeric>\n#include <queue>\n#include <string>\n#include <vector>\n#include <stdexcept>\n#include <fstream>\n#include <filesystem>\n#include <limits>\nusing namespace std;\nusing I=int64_t;\nint a=7,b=5,K=2048;size_t cap=9000000,wordcap=1000000;\nusing U=uint64_t;\nvector<U> tags;\nU mod_product=1;\nstring directory;\nint stage_number=0;\nstruct E {int v;string w;};using G=vector<vector<E>>;\nint mod(I x,int p){int r=x%p;return r<0?r+p:r;}\nint inv(int a,int p){int r=1;for(int n=p-2;n;n>>=1,a=I(a)*a%p)if(n&1)r=I(r)*a%p;return r;}\nint flo(int x,int b){int r=x%b;if(r<0)r+=b;return (x-r)/b;}\nint cval(char x){return int((unsigned char)x)-128;}\nchar enc(int c){return char(c+128);}\n\n// Sort by an intrinsic vertex name (residue modulo the primes used, cell).\n// All edge multiplicities are retained in this normalization.\nvoid canonicalize(G& g){\n size_t n=g.size(); if(tags.size()!=n)throw runtime_error("tag count mismatch");\n vector<int> order(n),idx(n);iota(order.begin(),order.end(),0);\n sort(order.begin(),order.end(),[&](int x,int y){return tags[x]<tags[y];});\n G sorted(n);vector<U> nt(n);\n for(size_t i=0;i<n;i++){idx[order[i]]=i;nt[i]=tags[order[i]];if(i&&nt[i]==nt[i-1])throw runtime_error("duplicate tag");}\n for(size_t i=0;i<n;i++){\n  sorted[i]=move(g[order[i]]);\n  for(auto& e:sorted[i]) e.v=idx[e.v];\n  sort(sorted[i].begin(),sorted[i].end(),[](const E&x,const E&y){return x.v<y.v||(x.v==y.v&&x.w<y.w);});\n }\n g=move(sorted);tags=move(nt);\n}\nvoid little(ofstream&f,U x,int bytes){for(int i=0;i<bytes;i++){f.put(char(x&255));x>>=8;}}\nvoid dump(const G&g,const string&suffix){\n string name=directory+"/"+to_string(stage_number)+"_"+suffix+".bin";\n ofstream f(name,ios::binary);if(!f)throw runtime_error("cannot open graph output");\n f.write("WORDGR01",8);little(f,mod_product,8);little(f,K,4);little(f,g.size(),8);\n for(size_t u=0;u<g.size();u++){\n  little(f,tags[u],8);little(f,g[u].size(),4);\n  for(const auto&e:g[u]){\n   if(e.w.empty()||e.w.size()>wordcap)throw runtime_error("invalid word length");\n   little(f,tags[e.v],8);little(f,e.w.size(),4);f.write(e.w.data(),e.w.size());\n  }\n }\n if(!f)throw runtime_error("graph output write failed");\n}\n\nstruct Summary{size_t n,e,cyc,cert,badn,branch,maxword,totalword;};\nG prune(G g,Summary& s){\n int n=g.size();s.n=n;s.e=0;for(auto&v:g)s.e+=v.size();\n vector<vector<int>>rev(n);for(int u=0;u<n;u++)for(auto&e:g[u])rev[e.v].push_back(u);\n vector<unsigned char>vis(n);vector<int>ord;ord.reserve(n);vector<pair<int,size_t>>stk;\n for(int root=0;root<n;root++)if(!vis[root]){vis[root]=1;stk.push_back({root,0});while(!stk.empty()){\n  auto&f=stk.back();int u=f.first;if(f.second<g[u].size()){int v=g[u][f.second++].v;if(!vis[v]){vis[v]=1;stk.push_back({v,0});}}else{ord.push_back(u);stk.pop_back();}\n }}\n vector<int>owner(n,-1),roots,sizes,st;\n for(auto it=ord.rbegin();it!=ord.rend();++it){int root=*it;if(owner[root]>=0)continue;int c=roots.size(),sz=0;roots.push_back(root);owner[root]=c;st.push_back(root);while(!st.empty()){int u=st.back();st.pop_back();sz++;for(int v:rev[u])if(owner[v]<0){owner[v]=c;st.push_back(v);}}sizes.push_back(sz);}\n rev.clear();rev.shrink_to_fit();\n int nc=roots.size();vector<I>h(n,-1),d(nc);vector<int>nie(nc),que;\n for(int c=0;c<nc;c++){h[roots[c]]=0;que.clear();que.push_back(roots[c]);for(size_t i=0;i<que.size();i++){int u=que[i];for(auto&e:g[u])if(owner[e.v]==c&&h[e.v]<0){h[e.v]=h[u]+e.w.size();que.push_back(e.v);}}}\n for(int u=0;u<n;u++)for(auto&e:g[u])if(owner[u]==owner[e.v]){int c=owner[u];nie[c]++;d[c]=gcd(d[c],abs(h[u]+I(e.w.size())-h[e.v]));}\n vector<unsigned char>bad(nc);vector<vector<int>>lab(nc);s.cyc=s.cert=s.badn=0;\n for(int c=0;c<nc;c++)if(nie[c]){s.cyc++;if(d[c]<=0)throw runtime_error("cycle length zero");if(d[c]>(I)wordcap)bad[c]=1;else lab[c].assign(d[c],999);}\n for(int u=0;u<n;u++)for(auto&e:g[u])if(owner[u]==owner[e.v]){int c=owner[u];if(bad[c])continue;I ph=h[u]%d[c];for(char letter:e.w){int v=cval(letter);if(lab[c][ph]==999)lab[c][ph]=v;else if(lab[c][ph]!=v){bad[c]=1;break;}ph++;if(ph==d[c])ph=0;}}\n for(int c=0;c<nc;c++)if(nie[c]){if(bad[c])s.badn+=sizes[c];else s.cert++;}\n // Drop intercomponent transitions: only eventual tails are needed.\n for(int u=0;u<n;u++){\n  auto&v=g[u];v.erase(remove_if(v.begin(),v.end(),[&](const E&e){return !bad[owner[u]]||owner[e.v]!=owner[u];}),v.end());\n  sort(v.begin(),v.end(),[](const E&x,const E&y){return x.v<y.v||(x.v==y.v&&x.w<y.w);});\n  v.erase(unique(v.begin(),v.end(),[](const E&x,const E&y){return x.v==y.v&&x.w==y.w;}),v.end());\n }\n // Recheck pure functional components after deduplication. Keeping one anchor\n // is safe even if all labels periodic; next prune will remove it.\n vector<int>id(n,-1);int count=0;\n for(int u=0;u<n;u++)if(bad[owner[u]]&&g[u].size()!=1&&g[u].size()>0)id[u]=count++;\n for(int c=0;c<nc;c++)if(bad[c]){bool has=false;for(int u=0;u<n&&!has;u++)if(owner[u]==c&&id[u]>=0)has=true;if(!has)id[roots[c]]=count++;}\n G out(count);vector<U> nt(count);for(int u=0;u<n;u++)if(id[u]>=0)nt[id[u]]=tags[u];s.maxword=s.totalword=0;\n for(int u=0;u<n;u++)if(id[u]>=0)for(auto&e:g[u]){\n  string w=e.w;int v=e.v;size_t steps=0;\n  while(id[v]<0){if(g[v].size()!=1)throw runtime_error("bad compressed path");w+=g[v][0].w;v=g[v][0].v;if(++steps>size_t(n)||w.size()>wordcap)throw runtime_error("inconclusive word cap");}\n  s.maxword=max(s.maxword,w.size());s.totalword+=w.size();out[id[u]].push_back({id[v],move(w)});\n }\n s.branch=count;tags=move(nt);return out;\n}\nG lift(const G&g,int p){\n if(size_t(g.size())*p>cap)throw runtime_error("inconclusive lift cap");\n vector<int>id(g.size()*p,-1);G h;vector<U> nt;\n if(mod_product%p==0)throw runtime_error("repeated prime");\n if(mod_product>numeric_limits<U>::max()/U(K*p))throw runtime_error("tag overflow");\n int mi=inv(mod_product%p,p);\n auto get=[&](int u,int q){int&v=id[size_t(u)*p+q];if(v<0){v=h.size();h.emplace_back();U oldq=tags[u]/K;U cell=tags[u]%K;\n U newq=oldq+mod_product*U(mod(I(q)-I(oldq%p),p)*mi%p);nt.push_back(newq*K+cell);}return v;};\n int ai=inv(a%p,p),bi=inv(b%p,p),ratio=a*bi%p,invr=b*ai%p;\n for(int u=0;u<(int)g.size();u++)for(auto&e:g[u]){\n  vector<unsigned char>forbid(p);forbid[0]=1;int weight=ai,root=0,alpha=1,beta=0,used=1;\n  for(char z:e.w){int c=cval(z);root=mod(root-I(c)*weight,p);if(!forbid[root]){forbid[root]=1;used++;}weight=weight*invr%p;alpha=alpha*ratio%p;beta=mod(I(ratio)*beta+I(c)*bi,p);if(used==p)break;}\n  if(used==p)continue;\n  for(int q=1;q<p;q++)if(!forbid[q]){int z=mod(I(alpha)*q+beta,p);if(!z)throw runtime_error("missed zero");int source=get(u,q),target=get(e.v,z);h[source].push_back({target,e.w});}\n }\n tags=move(nt);mod_product*=p;return h;\n}\nbool prime(int n){for(int d=2;d*d<=n;d++)if(n%d==0)return false;return n>=2;}\n\nint main(int argc,char**argv){\n if(argc!=2){cerr<<"Usage: construction_a OUTPUT_DIRECTORY\\n";return 1;}\n try{\n  directory=argv[1];filesystem::create_directories(directory);\n  G g(K);tags.resize(K);iota(tags.begin(),tags.end(),0);\n  for(int j=0;j<K;j++)for(int c:{-4,-2,2,4,6}){\n   int lo=max(0,flo(a*j-c*K,b)),hi=min(K-1,flo(a*(j+1)-c*K-1,b));\n   for(int k=lo;k<=hi;k++)g[j].push_back({k,string(1,enc(c))});\n  }\n  vector<int> primes={1,3,11,13};\n  for(int p:primes){\n   auto clock=chrono::steady_clock::now();\n   if(p!=1){if(!prime(p)||a*b%p==0)throw runtime_error("invalid prime");g=lift(g,p);}\n   canonicalize(g);dump(g,"input");\n   Summary s{};g=prune(move(g),s);\n   canonicalize(g);dump(g,"output");\n   size_t ne=0;for(auto&v:g)ne+=v.size();\n   cout<<"{\\"stage\\":"<<stage_number<<",\\"p\\":"<<p<<",\\"mod_product\\":"<<mod_product\n    <<",\\"input_vertices\\":"<<s.n<<",\\"input_edges\\":"<<s.e\n    <<",\\"cyclic\\":"<<s.cyc<<",\\"certified\\":"<<s.cert<<",\\"retained\\":"<<s.badn\n    <<",\\"macro_vertices\\":"<<g.size()<<",\\"macro_edges\\":"<<ne\n    <<",\\"max_word\\":"<<s.maxword<<",\\"total_word\\":"<<s.totalword\n    <<",\\"seconds\\":"<<chrono::duration<double>(chrono::steady_clock::now()-clock).count()<<"}"<<endl;\n   stage_number++;\n   if(g.empty())break;\n  }\n  if(!g.empty()){cerr<<"INCONCLUSIVE: graph is not empty\\n";return 2;}\n  cout<<"{\\"success\\":true,\\"prime_product_with_2_and_5\\":"<<10*mod_product<<"}"<<endl;\n }catch(const exception&e){cerr<<"INCONCLUSIVE/ERROR: "<<e.what()<<"\\n";return 2;}\n}\n'
SOURCE_B = '// Verification construction B for floor(xi*(7/5)^n).\n// Direct cell-pair tests, direct modular simulation along every word,\n// iterative Tarjan components, and checked forward/reverse connectivity.\n// This is a separately coded algorithmic cross-check, NOT a clean-room\n// provenance claim and NOT a proof-assistant/kernel formalization.\n// Build: g++ -std=c++17 -O2 checker_b.cpp -o checker_b\n// Run: ./checker_b OUTPUT_DIRECTORY\n#include <algorithm>\n#include <chrono>\n#include <cstdint>\n#include <filesystem>\n#include <fstream>\n#include <iostream>\n#include <numeric>\n#include <stdexcept>\n#include <string>\n#include <utility>\n#include <vector>\n\nnamespace {\nusing Word = std::string;\nusing U64 = std::uint64_t;\nusing I64 = std::int64_t;\nconstexpr int A=7, B=5, CELLS=2048;\nconstexpr std::size_t VERTEX_LIMIT=9000000;\nconstexpr std::size_t WORD_LIMIT=1000000;\n\nvoid require(bool x, const char* message) {\n    if (!x) throw std::runtime_error(message);\n}\nint residue(I64 x, int p) {\n    I64 y=x%p;\n    return int(y<0 ? y+p : y);\n}\nint inverse_by_search(int x, int p) {\n    for (int y=1; y<p; ++y) if (I64(x)*y%p==1) return y;\n    throw std::runtime_error("noninvertible coefficient");\n}\nint carry(char c) {return int(static_cast<unsigned char>(c))-128;}\nstruct Arc {int target; Word letters;};\nstruct Graph {\n    std::vector<std::vector<Arc>> out;\n    std::vector<U64> name;\n    U64 mod_product=1;\n};\nstruct Counts {\n    std::size_t input_vertices=0, input_edges=0, cyclic=0, certified=0;\n    std::size_t retained=0, macro_vertices=0, macro_edges=0;\n    std::size_t max_word=0, total_word=0;\n    std::size_t max_certified_period=0, max_certified_size=0;\n};\n\n// Canonical state name = (CRT residue)*4 + fractional-cell number.\nvoid normalize(Graph& graph) {\n    const int n=int(graph.out.size());\n    require(graph.name.size()==std::size_t(n),"name count mismatch");\n    std::vector<std::pair<U64,int>> permutation;\n    permutation.reserve(n);\n    for (int v=0; v<n; ++v) permutation.emplace_back(graph.name[v],v);\n    std::sort(permutation.begin(),permutation.end());\n    std::vector<int> new_index(n);\n    std::vector<U64> names(n);\n    for (int v=0; v<n; ++v) {\n        require(v==0 || permutation[v-1].first!=permutation[v].first,\n                "duplicate canonical name");\n        names[v]=permutation[v].first;\n        new_index[permutation[v].second]=v;\n    }\n    std::vector<std::vector<Arc>> edges(n);\n    for (int v=0; v<n; ++v) {\n        edges[v]=std::move(graph.out[permutation[v].second]);\n        for (auto& e:edges[v]) {\n            require(0<=e.target && e.target<n,"edge endpoint outside graph");\n            e.target=new_index[e.target];\n            require(!e.letters.empty() && e.letters.size()<=WORD_LIMIT,\n                    "empty or excessive edge word");\n        }\n        std::sort(edges[v].begin(),edges[v].end(),[](const Arc&x,const Arc&y){\n            return x.target==y.target ? x.letters<y.letters : x.target<y.target;\n        });\n    }\n    graph.name=std::move(names);\n    graph.out=std::move(edges);\n}\nvoid write_number(std::ofstream& stream, U64 x, int length) {\n    char buffer[8];\n    for (int k=0;k<length;k++) buffer[k]=char((x>>(8*k))&255);\n    stream.write(buffer,length);\n}\nvoid save_graph(const Graph& graph,const std::string& filename) {\n    std::ofstream f(filename,std::ios::binary);\n    require(bool(f),"could not create graph output");\n    f.write("WORDGR01",8);\n    write_number(f,graph.mod_product,8);\n    write_number(f,CELLS,4);\n    write_number(f,graph.out.size(),8);\n    for (int v=0;v<int(graph.out.size());++v) {\n        write_number(f,graph.name[v],8);\n        write_number(f,graph.out[v].size(),4);\n        for (const auto&e:graph.out[v]) {\n            write_number(f,graph.name[e.target],8);\n            write_number(f,e.letters.size(),4);\n            f.write(e.letters.data(),e.letters.size());\n        }\n    }\n    require(bool(f),"graph output write failed");\n}\nGraph initial_graph() {\n    Graph g;\n    g.out.resize(CELLS);\n    g.name.resize(CELLS);\n    for (int j=0;j<CELLS;++j) {\n        g.name[j]=j;\n        // Deliberately test every target, rather than use the interval formula.\n        for (int k=0;k<CELLS;++k) for (int c=-4;c<=6;++c) {\n            if (c%2!=0 || c==0) continue;\n            if (A*j-B*(k+1)<c*CELLS && c*CELLS<A*(j+1)-B*k)\n                g.out[j].push_back({k,Word(1,char(c+128))});\n        }\n    }\n    return g;\n}\n\n// Construct all Cartesian states, then remove only completely isolated ones.\n// Modular trajectories are directly evaluated at every position of every word.\nGraph add_prime(const Graph& old,int p) {\n    require(old.mod_product%p!=0,"repeated prime");\n    require(A%p!=0 && B%p!=0,"prime divides base coefficients");\n    const std::size_t count=old.out.size()*std::size_t(p-1);\n    require(count<=VERTEX_LIMIT,"INCONCLUSIVE: vertex limit");\n    const int inv_b=inverse_by_search(B%p,p);\n    const int inv_m=inverse_by_search(old.mod_product%p,p);\n    Graph full;\n    full.out.resize(count);\n    full.name.resize(count);\n    full.mod_product=old.mod_product*U64(p);\n    for (int u=0;u<int(old.out.size());++u) {\n        for (int q=1;q<p;++q) {\n            const int source=u*(p-1)+q-1;\n            const U64 oldq=old.name[u]/CELLS;\n            const U64 cell=old.name[u]%CELLS;\n            const int lift=residue((I64(q)-I64(oldq%p))*inv_m,p);\n            const U64 combined=oldq+old.mod_product*U64(lift);\n            full.name[source]=combined*CELLS+cell;\n            for (const Arc& edge:old.out[u]) {\n                int z=q;\n                for (char letter:edge.letters) {\n                    z=residue((I64(A)*z+carry(letter))*inv_b,p);\n                    if (z==0) break;\n                }\n                if (z!=0) full.out[source].push_back({edge.target*(p-1)+z-1,edge.letters});\n            }\n        }\n    }\n    std::vector<unsigned char> incident(count,0);\n    for (int u=0;u<int(count);++u) for(const auto&e:full.out[u]) {\n        incident[u]=1;incident[e.target]=1;\n    }\n    std::vector<int> renumber(count,-1);\n    Graph result;result.mod_product=full.mod_product;\n    for(int u=0;u<int(count);++u) if(incident[u]) {\n        renumber[u]=int(result.name.size());\n        result.name.push_back(full.name[u]);\n    }\n    result.out.resize(result.name.size());\n    for(int u=0;u<int(count);++u) if(incident[u]) {\n        auto& edges=result.out[renumber[u]];\n        edges=std::move(full.out[u]);\n        for(auto&e:edges) {\n            require(renumber[e.target]>=0,"removed nonisolated target");\n            e.target=renumber[e.target];\n        }\n    }\n    return result;\n}\n\n// Iterative Tarjan, independent of construction A\'s reverse-order Kosaraju.\nstd::vector<int> components(const Graph& g,int& component_count) {\n    const int n=int(g.out.size());\n    std::vector<int> number(n,-1),low(n),owner(n,-1),active;\n    std::vector<unsigned char> on_stack(n,0);\n    struct Frame {int vertex; std::size_t next_edge;};\n    std::vector<Frame> call_stack;\n    int time=0;component_count=0;\n    for (int root=0;root<n;++root) {\n        if(number[root]>=0)continue;\n        number[root]=low[root]=time++;\n        active.push_back(root);on_stack[root]=1;\n        call_stack.push_back({root,0});\n        while(!call_stack.empty()) {\n            int u=call_stack.back().vertex;\n            auto& next=call_stack.back().next_edge;\n            if(next<g.out[u].size()) {\n                int v=g.out[u][next++].target;\n                if(number[v]<0) {\n                    number[v]=low[v]=time++;\n                    active.push_back(v);on_stack[v]=1;\n                    call_stack.push_back({v,0});\n                } else if(on_stack[v]) {\n                    low[u]=std::min(low[u],number[v]);\n                }\n            } else {\n                call_stack.pop_back();\n                if(low[u]==number[u]) {\n                    while(true) {\n                        require(!active.empty(),"Tarjan stack underflow");\n                        int v=active.back();active.pop_back();on_stack[v]=0;\n                        owner[v]=component_count;\n                        if(v==u)break;\n                    }\n                    ++component_count;\n                }\n                if(!call_stack.empty()) {\n                    int parent=call_stack.back().vertex;\n                    low[parent]=std::min(low[parent],low[u]);\n                }\n            }\n        }\n    }\n    require(active.empty(),"Tarjan stack not exhausted");\n    for(int c:owner)require(c>=0 && c<component_count,"unassigned component");\n    return owner;\n}\n\nGraph remove_and_compress(Graph g,Counts& stats) {\n    const int n=int(g.out.size());\n    stats.input_vertices=n;\n    for(const auto&edges:g.out)stats.input_edges+=edges.size();\n    int nc=0;auto owner=components(g,nc);\n    std::vector<int> root(nc,-1),size(nc,0);\n    for(int v=0;v<n;++v) {\n        int c=owner[v];++size[c];\n        if(root[c]<0)root[c]=v;\n    }\n    // Explicitly check strong connectivity in both directions. Also check that\n    // the integer component number is a strict rank on every interblock edge.\n    std::vector<std::vector<int>> reverse(n);\n    for(int u=0;u<n;++u)for(const auto&e:g.out[u]) {\n        reverse[e.target].push_back(u);\n        if(owner[u]!=owner[e.target])\n            require(owner[u]>owner[e.target],"condensation rank does not decrease");\n    }\n    std::vector<I64> distance(n,-1);\n    std::vector<unsigned char> back_seen(n,0);\n    std::vector<int> stack;\n    for(int c=0;c<nc;++c) {\n        require(size[c]>0 && root[c]>=0,"empty component");\n        int seen=0;\n        distance[root[c]]=0;stack.push_back(root[c]);\n        while(!stack.empty()) {\n            int u=stack.back();stack.pop_back();++seen;\n            for(const auto&e:g.out[u])if(owner[e.target]==c && distance[e.target]<0) {\n                distance[e.target]=distance[u]+I64(e.letters.size());\n                stack.push_back(e.target);\n            }\n        }\n        require(seen==size[c],"component not forward connected");\n        seen=0;back_seen[root[c]]=1;stack.push_back(root[c]);\n        while(!stack.empty()) {\n            int v=stack.back();stack.pop_back();++seen;\n            for(int u:reverse[v])if(owner[u]==c && !back_seen[u]) {\n                back_seen[u]=1;stack.push_back(u);\n            }\n        }\n        require(seen==size[c],"component not reverse connected");\n    }\n    reverse.clear();reverse.shrink_to_fit();\n    std::vector<I64> period(nc,0);\n    std::vector<std::size_t> inside_edges(nc,0);\n    for(int u=0;u<n;++u)for(const auto&e:g.out[u])if(owner[u]==owner[e.target]) {\n        int c=owner[u];++inside_edges[c];\n        I64 gap=distance[u]+I64(e.letters.size())-distance[e.target];\n        if(gap<0)gap=-gap;\n        period[c]=std::gcd(period[c],gap);\n    }\n    std::vector<unsigned char> bad(nc,0);\n    std::vector<std::vector<int>> phases(nc);\n    for(int c=0;c<nc;++c)if(inside_edges[c]) {\n        ++stats.cyclic;\n        require(period[c]>0,"cyclic block has zero period");\n        if(period[c]>I64(WORD_LIMIT))bad[c]=1;\n        else phases[c].assign(std::size_t(period[c]),1000);\n    }\n    for(int u=0;u<n;++u)for(const auto&e:g.out[u])if(owner[u]==owner[e.target]) {\n        int c=owner[u];if(bad[c])continue;\n        require((distance[u]+I64(e.letters.size())-distance[e.target])%period[c]==0,\n                "phase increment incorrect");\n        for(std::size_t k=0;k<e.letters.size();++k) {\n            const I64 phase=(distance[u]+I64(k))%period[c];\n            int letter=carry(e.letters[k]);\n            int& recorded=phases[c][phase];\n            if(recorded==1000)recorded=letter;\n            else if(recorded!=letter){bad[c]=1;break;}\n        }\n    }\n    for(int c=0;c<nc;++c)if(inside_edges[c]) {\n        if(bad[c])stats.retained+=size[c];\n        else {\n            ++stats.certified;\n            stats.max_certified_period=std::max(stats.max_certified_period,std::size_t(period[c]));\n            stats.max_certified_size=std::max(stats.max_certified_size,std::size_t(size[c]));\n            for(int letter:phases[c])require(letter!=1000,"unused periodic phase");\n        }\n    }\n    // Keep all and only internal edges in uncertified components. Deduplicate\n    // only identical edges, never distinct words with the same endpoints.\n    for(int u=0;u<n;++u) {\n        std::vector<Arc> keep;\n        if(bad[owner[u]])for(auto&e:g.out[u])if(owner[e.target]==owner[u])\n            keep.push_back(std::move(e));\n        std::sort(keep.begin(),keep.end(),[](const Arc&x,const Arc&y){\n            return x.target==y.target ? x.letters<y.letters : x.target<y.target;\n        });\n        keep.erase(std::unique(keep.begin(),keep.end(),[](const Arc&x,const Arc&y){\n            return x.target==y.target && x.letters==y.letters;\n        }),keep.end());\n        g.out[u]=std::move(keep);\n    }\n    std::vector<unsigned char> anchor(n,0),has_anchor(nc,0);\n    for(int u=0;u<n;++u)if(bad[owner[u]]) {\n        require(!g.out[u].empty(),"retained component has a dead end");\n        if(g.out[u].size()>1){anchor[u]=1;has_anchor[owner[u]]=1;}\n    }\n    for(int c=0;c<nc;++c)if(bad[c] && !has_anchor[c])anchor[root[c]]=1;\n    Graph result;result.mod_product=g.mod_product;\n    std::vector<int> mapping(n,-1);\n    for(int u=0;u<n;++u)if(anchor[u]) {\n        mapping[u]=int(result.name.size());result.name.push_back(g.name[u]);\n    }\n    result.out.resize(result.name.size());\n    for(int u=0;u<n;++u)if(anchor[u])for(const auto&first:g.out[u]) {\n        Word full_word=first.letters;\n        int v=first.target;\n        std::size_t traversed=1;\n        while(!anchor[v]) {\n            require(g.out[v].size()==1,"nonunique suppressed continuation");\n            const auto& next=g.out[v][0];\n            full_word.append(next.letters);v=next.target;\n            require(++traversed<=std::size_t(n)+1,"closed suppressed cycle");\n            require(full_word.size()<=WORD_LIMIT,"INCONCLUSIVE: word limit");\n        }\n        require(mapping[v]>=0,"missing compressed endpoint");\n        ++stats.macro_edges;\n        stats.max_word=std::max(stats.max_word,full_word.size());\n        stats.total_word+=full_word.size();\n        result.out[mapping[u]].push_back({mapping[v],std::move(full_word)});\n    }\n    stats.macro_vertices=result.out.size();\n    return result;\n}\n} // namespace\n\nint main(int argc,char**argv) {\n    if(argc!=2){std::cerr<<"Usage: checker_b OUTPUT_DIRECTORY\\n";return 1;}\n    try {\n        const std::string directory=argv[1];\n        std::filesystem::create_directories(directory);\n        Graph graph=initial_graph();\n        const std::vector<int> primes={1,3,11,13};\n        int stage=0;\n        for(int p:primes) {\n            auto begin=std::chrono::steady_clock::now();\n            if(p!=1)graph=add_prime(graph,p);\n            normalize(graph);\n            save_graph(graph,directory+"/"+std::to_string(stage)+"_input.bin");\n            Counts counts;\n            graph=remove_and_compress(std::move(graph),counts);\n            normalize(graph);\n            save_graph(graph,directory+"/"+std::to_string(stage)+"_output.bin");\n            std::cout<<"{\\"stage\\":"<<stage<<",\\"p\\":"<<p\n                <<",\\"mod_product\\":"<<graph.mod_product\n                <<",\\"input_vertices\\":"<<counts.input_vertices\n                <<",\\"input_edges\\":"<<counts.input_edges\n                <<",\\"cyclic\\":"<<counts.cyclic\n                <<",\\"certified\\":"<<counts.certified\n                <<",\\"retained\\":"<<counts.retained\n                <<",\\"macro_vertices\\":"<<counts.macro_vertices\n                <<",\\"macro_edges\\":"<<counts.macro_edges\n                <<",\\"max_word\\":"<<counts.max_word\n                <<",\\"total_word\\":"<<counts.total_word\n                <<",\\"max_certified_period\\":"<<counts.max_certified_period\n                <<",\\"max_certified_size\\":"<<counts.max_certified_size\n                <<",\\"seconds\\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()\n                <<"}"<<std::endl;\n            ++stage;\n            if(graph.out.empty())break;\n        }\n        require(graph.out.empty(),"INCONCLUSIVE: final graph is not empty");\n        std::cout<<"{\\"success\\":true,\\"prime_product_with_2_and_5\\":"<<10*graph.mod_product<<"}"<<std::endl;\n    } catch(const std::exception& error) {\n        std::cerr<<"INCONCLUSIVE/ERROR: "<<error.what()<<"\\n";return 2;\n    }\n}\n'

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--workdir',default='cross-check-75')
    args=parser.parse_args()
    root=Path(args.workdir).resolve()
    if root.exists():
        raise SystemExit('Choose a fresh work directory; existing data are not overwritten.')
    root.mkdir(parents=True)
    for name,source in [('A',SOURCE_A),('B',SOURCE_B)]:
        src=root/f'cross_{name}.cpp';src.write_text(source)
        exe=root/f'cross_{name}'
        subprocess.run(['g++','-O2','-std=c++17',str(src),'-o',str(exe)],check=True,timeout=120)
        run=subprocess.run([str(exe),str(root/f'out_{name}')],capture_output=True,text=True,timeout=120)
        (root/f'run_{name}.jsonl').write_text(run.stdout)
        if run.returncode!=0:
            raise RuntimeError(f'Construction {name} failed or was inconclusive: {run.stderr}')
    names_a={p.name for p in (root/'out_A').glob('*.bin')}
    names_b={p.name for p in (root/'out_B').glob('*.bin')}
    if names_a!=names_b or len(names_a)!=8:
        raise RuntimeError('Unexpected or unequal graph file sets')
    checks=[]
    for name in sorted(names_a):
        x=(root/'out_A'/name).read_bytes();y=(root/'out_B'/name).read_bytes()
        if x!=y:
            raise RuntimeError(f'Complete graph mismatch: {name}')
        checks.append({'name':name,'bytes':len(x),'sha256':hashlib.sha256(x).hexdigest()})
    stages={k:[json.loads(x) for x in (root/f'run_{k}.jsonl').read_text().splitlines()] for k in ('A','B')}
    for k in ('A','B'):
        if not stages[k][-1].get('success') or stages[k][-2]['macro_vertices']!=0:
            raise RuntimeError('Missing finite success')
    result={'a':7,'b':5,'K':2048,'carry_set':[-4,-2,2,4,6],
        'added_primes':[3,11,13],'covered_prime_product':4290,
        'all_full_graphs_equal':True,'files':checks,
        'compared_bytes':sum(x['bytes'] for x in checks),'stages':stages}
    (root/'cross_check.json').write_text(json.dumps(result,indent=2))
    print(json.dumps(result,indent=2))
if __name__=='__main__':
    main()
